import{_ as e,a,b as i,c as r,d as n,e as s,f as o}from"./chunks/remove-4.C7c7eI4u.js";import{_ as l,o as g,c as h,a5 as d}from"./chunks/framework.CcrBcQWS.js";const x=JSON.parse('{"title":"Rail & spring nut","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/hardware/rail-spring-nut.md","filePath":"manual/hardware/rail-spring-nut.md","lastUpdated":1787021357000}'),u={name:"manual/hardware/rail-spring-nut.md"};function p(c,t,m,f,_,y){return g(),h("div",null,[...t[0]||(t[0]=[d('<h1 id="rail-spring-nut" tabindex="-1">Rail &amp; spring nut <a class="header-anchor" href="#rail-spring-nut" aria-label="Permalink to &quot;Rail &amp; spring nut&quot;">​</a></h1><p>The robot uses <strong>rails</strong> for mounting optional hardware such as <strong>PTZ cameras</strong>, <strong>LiDAR</strong> units, and related brackets. <strong>Spring nuts</strong> inserted into the rail slot provide threaded anchor points for bolts.</p><h2 id="purchase-links" tabindex="-1">Purchase links <a class="header-anchor" href="#purchase-links" aria-label="Permalink to &quot;Purchase links&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Region</th><th>MISUMI product page</th></tr></thead><tbody><tr><td>South Korea</td><td><a href="https://kr.misumi-ec.com/vona2/detail/110302608410/?HissuCode=SHNTP5-5&amp;PNSearch=SHNTP5-5&amp;searchFlow=results2products&amp;list=PageSearchResult" target="_blank" rel="noreferrer">SHNTP5-5 (kr.misumi-ec.com)</a></td></tr><tr><td>United States</td><td><a href="https://us.misumi-ec.com/vona2/detail/110302247640/?PNSearch=SHNTP5-5&amp;HissuCode=SHNTP5-5&amp;seriesCode=110302247640&amp;tab=drawingAndSpecifications&amp;Page=1" target="_blank" rel="noreferrer">SHNTP5-5 (us.misumi-ec.com)</a></td></tr></tbody></table><h2 id="inserting-a-spring-nut" tabindex="-1">Inserting a spring nut <a class="header-anchor" href="#inserting-a-spring-nut" aria-label="Permalink to &quot;Inserting a spring nut&quot;">​</a></h2><ol><li><strong>Insert at an angle.</strong> Slide the spring nut <strong>diagonally</strong> into the rail slot so it enters the internal channel.</li><li><strong>Press the part that sticks out.</strong> A portion of the nut may sit <strong>proud of the slot</strong>; press it so the nut seats fully in the channel.</li><li><strong>Align with the rail.</strong> Adjust the nut so it is <strong>aligned with the slot</strong> and can slide along the rail as needed.</li></ol><figure style="text-align:center;"><img src="'+e+'" alt="Insert spring nut diagonally into the rail" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 1 - diagonal insert</figcaption></figure><figure style="text-align:center;"><img src="'+a+'" alt="Press the portion protruding outside the rail" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 2 - press the protruding section</figcaption></figure><figure style="text-align:center;"><img src="'+i+'" alt="Align the nut with the rail slot" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 3 - align with the slot</figcaption></figure><h2 id="removing-a-spring-nut" tabindex="-1">Removing a spring nut <a class="header-anchor" href="#removing-a-spring-nut" aria-label="Permalink to &quot;Removing a spring nut&quot;">​</a></h2><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p><strong>Tool diameter</strong></p><p>Use a rigid rod <strong>no larger than 4 mm</strong> in diameter. A thicker tool can damage the nut or mar the rail slot.</p></div></div><ol><li><strong>Insert a rod into the nut.</strong> Pass a <strong>rigid rod</strong> (<strong>≤ 4 mm</strong> diameter) through the hole in the spring nut.</li><li><strong>Push to one wall.</strong> Push the nut <strong>against one inner wall</strong> of the rail slot.</li><li><strong>Twist and lift.</strong> While holding it against that wall, <strong>twist and lift</strong> the nut toward the <strong>opposite</strong> side of the slot so it can clear the profile and release from the rail.</li><li><strong>Remove.</strong> Withdraw the nut from the slot.</li></ol><figure style="text-align:center;"><img src="'+r+'" alt="Insert rod into spring nut hole" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 1 - rod through the hole</figcaption></figure><figure style="text-align:center;"><img src="'+n+'" alt="Push nut against one wall of the rail" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 2 - push to one wall</figcaption></figure><figure style="text-align:center;"><img src="'+s+'" alt="Twist and lift away from the wall" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 3 - twist and lift</figcaption></figure><figure style="text-align:center;"><img src="'+o+'" alt="Remove spring nut from rail" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 4 - remove</figcaption></figure>',16)])])}const S=l(u,[["render",p]]);export{x as __pageData,S as default};
